// Writes packages/plugin-sdk/api-report.d.ts: the public plugin API as declared types (run after `pnpm build`).
// CI regenerates it and fails on any difference, so an API change is always a reviewed, deliberate change
// (and, after 1.0, a major version + an ADR when it breaks plugins).
import {readdirSync, readFileSync, writeFileSync} from "node:fs";
import {join, relative} from "node:path";

const dist = new URL("../packages/plugin-sdk/dist/", import.meta.url).pathname;
const files = (dir) =>
    readdirSync(dir, {withFileTypes: true}).flatMap((entry) =>
        entry.isDirectory() ? files(join(dir, entry.name)) : entry.name.endsWith(".d.ts") ? [join(dir, entry.name)] : []
    );

const body = files(dist)
    .sort()
    .map((file) => {
        const content = readFileSync(file, "utf8")
            .replace(/\/\/# sourceMappingURL=.*\n?/g, "")
            .trim();
        return `// ---- ${relative(dist, file)}\n${content}\n`;
    })
    .join("\n");
writeFileSync(
    new URL("../packages/plugin-sdk/api-report.d.ts", import.meta.url),
    `// Generated by scripts/api-report.mjs — do not edit. Public API of @aicd-ci/plugin-sdk.\n\n${body}`
);
console.log("packages/plugin-sdk/api-report.d.ts written");
